/* ══════════════════════════════════════════════════════════════════════
 *  CONFIG  —  فقط این بخش را ویرایش کنید / Edit only this block
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = {
  chatId:   '<<TELEGRAM_CHAT_ID>>',  // آی‌دی چت مقصد / target chat id
  lang:     'fa',                    // 'fa' | 'en'
  tz:       'Asia/Tehran',           // منطقه زمانی / IANA timezone
  maxTasks: 15,                      // حداکثر کار در پیام / max tasks in message
  showJalali: true,                  // نمایش تاریخ شمسی / show Persian date
};
/* ══════════════════════════════════════════════════════════════════════ */

const OPEN = ['todo', 'doing', 'blocked', 'in progress', ''];
const PRIO = { high: 0, بالا: 0, urgent: 0, med: 1, medium: 1, متوسط: 1, low: 2, پایین: 2, '': 1 };

const L = {
  fa: {
    hi: '☀️ <b>صبح بخیر!</b>',
    none: 'هیچ کار بازی برای امروز ثبت نشده. با <code>/task عنوان کار</code> کار جدید اضافه کن.',
    open: 'کار باز',
    overdue: '⚠️ عقب‌افتاده',
    today: '🎯 امروز',
    later: '🗓 بعداً',
    footer: 'با <code>/done شماره</code> کار را ببند · <code>/task</code> برای افزودن · <code>/help</code> راهنما',
    more: 'و %d مورد دیگر…',
    p: { 0: '🔴', 1: '🟡', 2: '⚪️' },
  },
  en: {
    hi: '☀️ <b>Good morning!</b>',
    none: 'No open tasks for today. Add one with <code>/task your task</code>.',
    open: 'open task(s)',
    overdue: '⚠️ Overdue',
    today: '🎯 Today',
    later: '🗓 Later',
    footer: 'Close with <code>/done number</code> · <code>/task</code> to add · <code>/help</code>',
    more: 'and %d more…',
    p: { 0: '🔴', 1: '🟡', 2: '⚪️' },
  },
};
const t = L[CFG.lang] || L.en;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// «چهارشنبه ۱۴ مرداد ۱۴۰۵» — اجزا را دستی می‌چینیم چون Intl ترتیب را جابه‌جا می‌دهد
// Assemble the parts manually; Intl emits them in an awkward order here.
const jalali = (iso) => {
  if (!CFG.showJalali) return '';
  try {
    const p = new Intl.DateTimeFormat('fa-IR-u-ca-persian', {
      weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: CFG.tz,
    }).formatToParts(new Date(iso + 'T09:00:00'));
    const g = (type) => (p.find((x) => x.type === type) || {}).value || '';
    const [wd, d, m, y] = [g('weekday'), g('day'), g('month'), g('year')];
    return d && m && y ? `${wd ? wd + ' ' : ''}${d} ${m} ${y}` : '';
  } catch (e) { return ''; }
};

const now   = $now.setZone(CFG.tz);
const today = now.toISODate();

// خواندن ردیف‌ها؛ اگر شیت خالی باشد آرایه خالی است / read rows, empty-safe
const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => String(r.task || '').trim() !== '');

const openRows = rows.filter((r) => OPEN.includes(String(r.status || '').trim().toLowerCase()));

// دسته‌بندی بر اساس سررسید / bucket by due date
const overdue = [], due = [], later = [];
for (const r of openRows) {
  const d = String(r.due || '').trim().slice(0, 10);
  if (d && d < today) overdue.push(r);
  else if (!d || d === today) due.push(r);
  else later.push(r);
}

const byPrio = (a, b) => {
  const pa = PRIO[String(a.priority || '').trim().toLowerCase()] ?? 1;
  const pb = PRIO[String(b.priority || '').trim().toLowerCase()] ?? 1;
  return pa - pb;
};
overdue.sort(byPrio); due.sort(byPrio); later.sort(byPrio);

// شماره‌گذاری پایدار در کل پیام / stable numbering across the whole message
let n = 0;
const line = (r) => {
  n += 1;
  const p = PRIO[String(r.priority || '').trim().toLowerCase()] ?? 1;
  const tags = String(r.tags || '').trim();
  return `${n}. ${t.p[p]} ${esc(r.task)}${tags ? ` <i>#${esc(tags.replace(/[\s,]+/g, ' #'))}</i>` : ''}`;
};

const section = (title, list) => (list.length ? [`\n<b>${title}</b>`, ...list.map(line)] : []);

const parts = [t.hi];
const jd = jalali(today);
parts.push(`<i>${jd ? esc(jd) + ' · ' : ''}${today}</i>`);

const total = overdue.length + due.length + later.length;
if (total === 0) {
  parts.push('\n' + t.none);
} else {
  parts.push(`\n📌 <b>${total}</b> ${t.open}`);
  const shown = [...section(t.overdue, overdue), ...section(t.today, due), ...section(t.later, later)];
  // برش امن روی سقف تعیین‌شده / trim safely to the configured cap
  let count = 0, out = [];
  for (const l of shown) {
    if (/^\d+\./.test(l)) { if (count >= CFG.maxTasks) continue; count += 1; }
    out.push(l);
  }
  parts.push(...out);
  if (total > CFG.maxTasks) parts.push('\n' + t.more.replace('%d', String(total - CFG.maxTasks)));
}
parts.push(`\n———\n${t.footer}`);

return [{
  json: {
    chatId: CFG.chatId,
    message: parts.join('\n'),
    date: today,
    stats: { total, overdue: overdue.length, today: due.length, later: later.length },
  },
}];

/* ══════════════════════════════════════════════════════════════════════
 *  CONFIG  —  فقط این بخش را ویرایش کنید / Edit only this block
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = {
  chatId: '<<TELEGRAM_CHAT_ID>>',
  lang:   'fa',
  tz:     'Asia/Tehran',
};
/* ══════════════════════════════════════════════════════════════════════ */

const DONE = ['done', 'completed', 'انجام شد', 'تمام'];

const L = {
  fa: {
    hi: '🌆 <b>وقت گزارش روزانه</b>',
    doneToday: '✅ امروز بستی',
    stillOpen: '⏳ هنوز باز',
    ask: 'در یک پیام بنویس امروز چه کردی. هر خط = یک مورد.',
    hint: 'اختیاری در انتهای پیام: <code>ساعت: 6.5</code> · <code>حال: خوب</code> · <code>#تگ</code>',
    example: '<i>مثال:\nجلسه با تیم فروش\nرفع باگ لاگین\nساعت: 7 حال: خوب #بک‌اند</i>',
    skip: 'اگر امروز مرخصی بودی بنویس: <code>/off</code>',
  },
  en: {
    hi: '🌆 <b>Daily report time</b>',
    doneToday: '✅ Closed today',
    stillOpen: '⏳ Still open',
    ask: 'Reply in one message with what you did today. One line = one item.',
    hint: 'Optional at the end: <code>hours: 6.5</code> · <code>mood: good</code> · <code>#tag</code>',
    example: '<i>Example:\nSales team sync\nFixed login bug\nhours: 7 mood: good #backend</i>',
    skip: 'Day off? Just send: <code>/off</code>',
  },
};
const t = L[CFG.lang] || L.en;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const now   = $now.setZone(CFG.tz);
const today = now.toISODate();

const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => String(r.task || '').trim() !== '');

const isDone = (r) => DONE.includes(String(r.status || '').trim().toLowerCase());

const closedToday = rows.filter((r) => isDone(r) && String(r.done_at || '').slice(0, 10) === today);
const stillOpen   = rows.filter((r) => !isDone(r));

const parts = [t.hi, `<i>${today}</i>`];

if (closedToday.length) {
  parts.push(`\n<b>${t.doneToday} (${closedToday.length})</b>`);
  parts.push(...closedToday.slice(0, 10).map((r) => `• ${esc(r.task)}`));
}
if (stillOpen.length) {
  parts.push(`\n<b>${t.stillOpen} (${stillOpen.length})</b>`);
  parts.push(...stillOpen.slice(0, 10).map((r) => `• ${esc(r.task)}`));
}

parts.push(`\n———\n${t.ask}`);
parts.push(t.hint);
parts.push('\n' + t.example);
parts.push('\n' + t.skip);

return [{
  json: {
    chatId: CFG.chatId,
    message: parts.join('\n'),
    date: today,
    prefilledDone: closedToday.length,
  },
}];

/* ══════════════════════════════════════════════════════════════════════
 *  📊 MONTHLY ROLL-UP
 *  آرشیو گزارش‌های ماه گذشته را به یک سند ارزیابی عملکرد تبدیل می‌کند.
 *  Turns last month's archive into a performance-review document.
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = {
  chatId:     '<<TELEGRAM_CHAT_ID>>',
  lang:       'fa',
  tz:         'Asia/Tehran',
  workdays:   [6, 0, 1, 2, 3],  // شنبه..چهارشنبه / Sat..Wed (0=Sun … 6=Sat)
  topTags:    6,
  highlights: 8,
};
/* ══════════════════════════════════════════════════════════════════════ */

const L = {
  fa: {
    title: '📊 <b>گزارش ماهانهٔ عملکرد</b>',
    none: 'برای ماه گذشته هیچ گزارشی در آرشیو نیست.',
    days: 'روز گزارش‌شده', cover: 'پوشش', tasks: 'کار انجام‌شده',
    hours: 'ساعت کارکرد', avg: 'میانگین روزانه', streak: 'بیشترین روز پیاپی',
    off: 'روز مرخصی', tags: '🏷 <b>حوزه‌های کاری</b>', hl: '⭐️ <b>مهم‌ترین دستاوردها</b>',
    best: '🏆 <b>پرکارترین روز</b>', foot: 'این متن را مستقیم در جلسهٔ ارزیابی عملکرد استفاده کن. آرشیو کامل در گوگل‌شیت است.',
    mon: ['ژانویه','فوریه','مارس','آوریل','مه','ژوئن','ژوئیه','اوت','سپتامبر','اکتبر','نوامبر','دسامبر'],
  },
  en: {
    title: '📊 <b>Monthly performance report</b>',
    none: 'No reports archived for last month.',
    days: 'days reported', cover: 'coverage', tasks: 'tasks completed',
    hours: 'hours logged', avg: 'daily average', streak: 'longest streak',
    off: 'days off', tags: '🏷 <b>Focus areas</b>', hl: '⭐️ <b>Highlights</b>',
    best: '🏆 <b>Most productive day</b>', foot: 'Paste this straight into your performance review. Full archive lives in Google Sheets.',
    mon: ['January','February','March','April','May','June','July','August','September','October','November','December'],
  },
};
const t = L[CFG.lang] || L.en;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const now  = $now.setZone(CFG.tz);
const last = now.minus({ months: 1 });
const from = last.startOf('month').toISODate();
const to   = last.endOf('month').toISODate();

// «تیر ۱۴۰۵» — ترتیب ماه/سال را دستی می‌چینیم چون Intl معکوس می‌دهد
// Build "month year" manually; Intl emits the parts in the reverse order here.
const jalaliMonth = (() => {
  try {
    const p = new Intl.DateTimeFormat('fa-IR-u-ca-persian-nu-latn', {
      year: 'numeric', month: 'long', timeZone: CFG.tz,
    }).formatToParts(new Date(from + 'T12:00:00'));
    const g = (type) => (p.find((x) => x.type === type) || {}).value || '';
    const m = g('month'), y = g('year');
    return m && y ? `${m} ${y}` : '';
  } catch (e) { return ''; }
})();

const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => {
    const d = String(r.date || '').slice(0, 10);
    return d >= from && d <= to;
  })
  .sort((a, b) => String(a.date).localeCompare(String(b.date)));

const header = `${t.title}\n<i>${jalaliMonth ? esc(jalaliMonth) + ' · ' : ''}${t.mon[last.month - 1]} ${last.year} (${from} → ${to})</i>`;

if (!rows.length) {
  return [{ json: { chatId: CFG.chatId, message: `${header}\n\n${t.none}`, period: { from, to }, empty: true } }];
}

const offDays  = rows.filter((r) => String(r.mood || '').toLowerCase() === 'off' || String(r.report || '') === 'OFF');
const workRows = rows.filter((r) => !offDays.includes(r));

const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const totalTasks = workRows.reduce((s, r) => s + num(r.done_count), 0);
const totalHours = workRows.reduce((s, r) => s + num(r.hours), 0);

// روزهای کاری ماه گذشته / expected workdays in the period
const isWorkday = (iso) => {
  const dt = last.set({ day: Number(String(iso).slice(8, 10)) });
  return CFG.workdays.includes(dt.weekday % 7);
};
let expected = 0;
for (let d = last.startOf('month'); d <= last.endOf('month'); d = d.plus({ days: 1 })) {
  if (CFG.workdays.includes(d.weekday % 7)) expected += 1;
}
// پوشش = روزهای کاریِ گزارش‌شده ÷ روزهای کاری ماه (گزارش‌های تعطیلات پوشش را از ۱۰۰٪ رد نمی‌کنند)
// Coverage counts reports on workdays only, so weekend reports can't push it past 100%.
const reportedWorkdays = rows.filter((r) => isWorkday(r.date)).length;
const coverage = expected ? Math.min(100, Math.round((reportedWorkdays / expected) * 100)) : 0;

// طولانی‌ترین زنجیرهٔ روزهای پیاپی / longest consecutive-day streak
let streak = 0, run = 0, prev = null;
for (const r of rows) {
  const d = String(r.date).slice(0, 10);
  run = (prev && new Date(d) - new Date(prev) === 86400000) ? run + 1 : 1;
  streak = Math.max(streak, run);
  prev = d;
}

// تگ‌های پرتکرار / most frequent tags
const tagCount = {};
for (const r of rows) {
  String(r.tags || '').split(/[,\s]+/).filter(Boolean)
    .forEach((tg) => { tagCount[tg] = (tagCount[tg] || 0) + 1; });
}
const topTags = Object.entries(tagCount).sort((a, b) => b[1] - a[1]).slice(0, CFG.topTags);

// پرکارترین روز / best day
const best = workRows.slice().sort((a, b) => num(b.done_count) - num(a.done_count))[0];

// دستاوردهای شاخص: بلندترین خطوط از پرکارترین روزها / highlights
const highlights = [];
for (const r of workRows.slice().sort((a, b) => num(b.done_count) - num(a.done_count))) {
  for (const line of String(r.report || '').split(/\r?\n/).map((l) => l.trim()).filter(Boolean)) {
    if (line.length >= 12 && !highlights.some((h) => h.line === line)) {
      highlights.push({ line, date: String(r.date).slice(0, 10) });
    }
    if (highlights.length >= CFG.highlights) break;
  }
  if (highlights.length >= CFG.highlights) break;
}

const parts = [header, ''];
parts.push(`📅 <b>${rows.length}</b> ${t.days} · ${t.cover} <b>${coverage}%</b>`);
parts.push(`✅ <b>${totalTasks}</b> ${t.tasks}`);
if (totalHours > 0) {
  parts.push(`⏱ <b>${Math.round(totalHours * 10) / 10}</b> ${t.hours} · ${t.avg} <b>${(totalHours / (workRows.length || 1)).toFixed(1)}</b>`);
}
parts.push(`🔥 ${t.streak}: <b>${streak}</b>`);
if (offDays.length) parts.push(`🌴 <b>${offDays.length}</b> ${t.off}`);

if (best) {
  parts.push(`\n${t.best}`);
  parts.push(`<code>${String(best.date).slice(0, 10)}</code> — ${num(best.done_count)} ${t.tasks}`);
}
if (topTags.length) {
  parts.push(`\n${t.tags}`);
  parts.push(topTags.map(([k, v]) => `#${esc(k)} <b>${v}</b>`).join(' · '));
}
if (highlights.length) {
  parts.push(`\n${t.hl}`);
  parts.push(...highlights.map((h) => `• ${esc(h.line)} <i>(${h.date})</i>`));
}
parts.push(`\n———\n<i>${t.foot}</i>`);

return [{
  json: {
    chatId: CFG.chatId,
    message: parts.join('\n'),
    period: { from, to },
    empty: false,
    metrics: {
      daysReported: rows.length, reportedWorkdays, expectedWorkdays: expected, coverage,
      tasksCompleted: totalTasks, hoursLogged: Math.round(totalHours * 10) / 10,
      longestStreak: streak, daysOff: offDays.length,
      topTags: topTags.map(([k, v]) => ({ tag: k, count: v })),
    },
  },
}];

/* ══════════════════════════════════════════════════════════════════════
 *  🔀 NORMALIZE INPUT  —  تنها نقطهٔ وابسته به کانال ورودی
 *  THE ONLY CHANNEL-DEPENDENT NODE.
 *
 *  برای تعویض تلگرام با فرم وب / واتساپ / ایمیل / بله / وبهوک:
 *  فقط نود تریگر قبلی و بلوک SOURCE پایین را عوض کنید. بقیهٔ ورک‌فلو
 *  دست‌نخورده کار می‌کند، چون همه‌چیز فقط این خروجی را می‌بیند:
 *
 *  To swap Telegram for a Web Form / WhatsApp / Email / Webhook:
 *  replace the trigger node and the SOURCE block below. The rest of the
 *  workflow is untouched — it only ever sees this contract:
 *
 *    { source, userId, userName, chatId, text, messageId, receivedAt }
 * ══════════════════════════════════════════════════════════════════════ */

/* ══════════════════════════════════════════════════════════════════════
 *  CONFIG
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = {
  // فهرست سفید — خالی یعنی همه مجازند (برای تست) / allowlist, empty = allow all
  allowedUserIds: [],           // e.g. [123456789]
  tz: 'Asia/Tehran',
};
/* ══════════════════════════════════════════════════════════════════════ */

const src = $json;

/* ─────────── SOURCE: TELEGRAM (فعال / active) ─────────── */
const msg = src.message || src.edited_message || {};
const out = {
  source:    'telegram',
  userId:    String(msg.from?.id ?? ''),
  userName:  String(msg.from?.username || msg.from?.first_name || ''),
  chatId:    String(msg.chat?.id ?? ''),
  text:      String(msg.text || msg.caption || '').trim(),
  messageId: msg.message_id ?? null,
};

/* ─────────── SOURCE: WEB FORM (n8n Form Trigger) ───────────
const out = {
  source:    'form',
  userId:    String(src['Employee ID'] || ''),
  userName:  String(src['Name'] || ''),
  chatId:    String(src['Employee ID'] || ''),
  text:      String(src['Report'] || ''),
  messageId: null,
};
─────────────────────────────────────────────────────────── */

/* ─────────── SOURCE: WEBHOOK / BALE / EITAA / WHATSAPP ───────────
const b = src.body || src;
const out = {
  source:    'webhook',
  userId:    String(b.from || b.sender || ''),
  userName:  String(b.name || ''),
  chatId:    String(b.chat_id || b.from || ''),
  text:      String(b.text || b.message || ''),
  messageId: b.id ?? null,
};
──────────────────────────────────────────────────────────────── */

/* ─────────── SOURCE: EMAIL (IMAP Trigger) ───────────
const out = {
  source:    'email',
  userId:    String(src.from || ''),
  userName:  String(src.from || ''),
  chatId:    String(src.from || ''),
  text:      String(src.textPlain || src.text || ''),
  messageId: src.messageId ?? null,
};
──────────────────────────────────────────────────── */

out.receivedAt  = $now.setZone(CFG.tz).toISO();
out.date        = $now.setZone(CFG.tz).toISODate();
out.authorized  = CFG.allowedUserIds.length === 0
  || CFG.allowedUserIds.map(String).includes(out.userId);

// دستور را از متن جدا کن / extract the leading command
const m = out.text.match(/^([\/+])([a-zA-Z؀-ۿ]*)\s*([\s\S]*)$/);
out.command = m ? (m[1] === '+' ? 'task' : (m[2] || '').toLowerCase()) : '';
out.args    = m ? String(m[3] || '').trim() : out.text;

return { json: out };

/* ══════════════════════════════════════════════════════════════════════
 *  🧾 PARSE TASK  —  «/task عنوان !بالا @1404-05-20 #تگ» را به ردیف شیت تبدیل می‌کند
 *  Turns "/task title !high @2026-08-20 #tag" into a sheet row.
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = { lang: 'fa', tz: 'Asia/Tehran' };

const PRIO_MAP = {
  high: 'high', h: 'high', بالا: 'high', فوری: 'high', urgent: 'high', '!': 'high',
  med: 'med', m: 'med', medium: 'med', متوسط: 'med',
  low: 'low', l: 'low', پایین: 'low', کم: 'low',
};

const L = {
  fa: { ok: '✅ ثبت شد', empty: '⚠️ عنوان کار خالی است. مثال: <code>/task تماس با مشتری !بالا @2026-08-10 #فروش</code>' },
  en: { ok: '✅ Task added', empty: '⚠️ Empty task. Example: <code>/task call client !high @2026-08-10 #sales</code>' },
};
const t = L[CFG.lang] || L.en;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const inp  = $json;
const now  = $now.setZone(CFG.tz);
let text   = String(inp.args || '').trim();

// !اولویت  /  !priority
let priority = 'med';
text = text.replace(/(^|\s)!([^\s]+)/g, (_, sp, v) => {
  const p = PRIO_MAP[String(v).toLowerCase()];
  if (p) { priority = p; return sp; }
  return _;
}).trim();

// @سررسید ISO  /  @due date
let due = '';
text = text.replace(/(^|\s)@(\d{4}-\d{2}-\d{2})/g, (_, sp, v) => { due = v; return sp; }).trim();

// #تگ‌ها  /  #tags
const tags = [];
text = text.replace(/(^|\s)#([^\s#]+)/g, (_, sp, v) => { tags.push(v); return sp; }).trim();

text = text.replace(/\s{2,}/g, ' ').trim();

if (!text) {
  return { json: { chatId: inp.chatId, ok: false, message: t.empty } };
}

const id = `T-${now.toFormat('yyyyLLdd')}-${String(now.toMillis()).slice(-5)}`;

const row = {
  id,
  date:       now.toISODate(),
  task:       text,
  priority,
  status:     'todo',
  tags:       tags.join(','),
  due,
  owner:      inp.userName || inp.userId || '',
  created_at: now.toISO(),
  done_at:    '',
};

const detail = [
  `<b>${esc(text)}</b>`,
  `اولویت / priority: <code>${priority}</code>`,
  due  ? `سررسید / due: <code>${due}</code>` : '',
  tags.length ? `#${tags.map(esc).join(' #')}` : '',
  `<code>${id}</code>`,
].filter(Boolean).join('\n');

return { json: { ...row, chatId: inp.chatId, ok: true, message: `${t.ok}\n\n${detail}` } };

/* ══════════════════════════════════════════════════════════════════════
 *  🎯 RESOLVE TASK TO CLOSE
 *  «/done 3» یا «/done بخشی از عنوان» را به ردیف دقیق شیت نگاشت می‌کند.
 *  Maps "/done 3" or "/done part of title" onto the exact sheet row.
 *  ورودی: ردیف‌های شیت Tasks / Input: rows of the Tasks sheet
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = { lang: 'fa', tz: 'Asia/Tehran' };

const OPEN = ['todo', 'doing', 'blocked', 'in progress', ''];
const PRIO = { high: 0, بالا: 0, urgent: 0, med: 1, medium: 1, متوسط: 1, low: 2, پایین: 2, '': 1 };

const L = {
  fa: {
    ok: '✅ <b>بسته شد</b>', left: 'کار باز باقی مانده',
    nf: '🤔 کاری با این مشخصات پیدا نشد. با <code>/list</code> شماره‌ها را ببین.',
    amb: '🤔 چند کار با این عبارت هست، دقیق‌تر بگو:',
    usage: 'استفاده: <code>/done 3</code> یا <code>/done بخشی از عنوان</code>',
  },
  en: {
    ok: '✅ <b>Marked done</b>', left: 'task(s) still open',
    nf: '🤔 No matching task. Use <code>/list</code> to see the numbers.',
    amb: '🤔 Several tasks match — be more specific:',
    usage: 'Usage: <code>/done 3</code> or <code>/done part of title</code>',
  },
};
const t = L[CFG.lang] || L.en;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const inp   = $('🔀 Normalize Input').first().json;
const now   = $now.setZone(CFG.tz);
const today = now.toISODate();
const q     = String(inp.args || '').trim();

const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => String(r.task || '').trim() !== '');

// همان ترتیبی که در پیام صبح شماره‌گذاری شد / same ordering as the morning message
const open = rows
  .filter((r) => OPEN.includes(String(r.status || '').trim().toLowerCase()))
  .map((r) => {
    const d = String(r.due || '').trim().slice(0, 10);
    return { r, bucket: d && d < today ? 0 : (!d || d === today ? 1 : 2),
             prio: PRIO[String(r.priority || '').trim().toLowerCase()] ?? 1 };
  })
  .sort((a, b) => a.bucket - b.bucket || a.prio - b.prio)
  .map((x) => x.r);

const fail = (message) => [{ json: { chatId: inp.chatId, ok: false, message } }];

if (!q) return fail(`${t.nf}\n${t.usage}`);

let hit = null;
if (/^\d+$/.test(q)) {
  hit = open[Number(q) - 1] || null;
} else {
  const needle = q.toLowerCase();
  const matches = open.filter((r) => String(r.task || '').toLowerCase().includes(needle));
  if (matches.length === 1) hit = matches[0];
  else if (matches.length > 1) {
    return fail(`${t.amb}\n` + matches.slice(0, 8)
      .map((r) => `• ${esc(r.task)}`).join('\n'));
  }
}

if (!hit) return fail(t.nf);

const remaining = open.length - 1;

return [{
  json: {
    id:      hit.id,
    task:    hit.task,
    status:  'done',
    done_at: now.toISO(),
    chatId:  inp.chatId,
    ok:      true,
    message: `${t.ok}\n\n• ${esc(hit.task)}\n\n📌 ${remaining} ${t.left}`,
  },
}];

/* ══════════════════════════════════════════════════════════════════════
 *  📋 BUILD TASK LIST  —  پاسخ به /list
 *  شماره‌ها دقیقاً همان شماره‌های /done هستند.
 *  Numbering matches /done exactly.
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = { lang: 'fa', tz: 'Asia/Tehran', max: 25 };

const OPEN = ['todo', 'doing', 'blocked', 'in progress', ''];
const PRIO = { high: 0, بالا: 0, urgent: 0, med: 1, medium: 1, متوسط: 1, low: 2, پایین: 2, '': 1 };
const ICON = { 0: '🔴', 1: '🟡', 2: '⚪️' };

const L = {
  fa: { title: '📋 <b>کارهای باز</b>', none: 'هیچ کار بازی نداری. 🎉', hint: 'برای بستن: <code>/done شماره</code>', od: 'عقب‌افتاده' },
  en: { title: '📋 <b>Open tasks</b>', none: 'No open tasks. 🎉', hint: 'To close: <code>/done number</code>', od: 'overdue' },
};
const t = L[CFG.lang] || L.en;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const inp   = $('🔀 Normalize Input').first().json;
const today = $now.setZone(CFG.tz).toISODate();

const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => String(r.task || '').trim() !== '');

const open = rows
  .filter((r) => OPEN.includes(String(r.status || '').trim().toLowerCase()))
  .map((r) => {
    const d = String(r.due || '').trim().slice(0, 10);
    return { r, bucket: d && d < today ? 0 : (!d || d === today ? 1 : 2),
             prio: PRIO[String(r.priority || '').trim().toLowerCase()] ?? 1, due: d };
  })
  .sort((a, b) => a.bucket - b.bucket || a.prio - b.prio);

if (!open.length) {
  return [{ json: { chatId: inp.chatId, message: `${t.title}\n\n${t.none}` } }];
}

const lines = open.slice(0, CFG.max).map((x, i) => {
  const tags = String(x.r.tags || '').trim();
  return `${i + 1}. ${ICON[x.prio]} ${esc(x.r.task)}`
    + (x.bucket === 0 ? ` <b>(${t.od})</b>` : '')
    + (x.due && x.bucket === 2 ? ` <i>@${x.due}</i>` : '')
    + (tags ? ` <i>#${esc(tags.replace(/[\s,]+/g, ' #'))}</i>` : '');
});

return [{
  json: {
    chatId: inp.chatId,
    message: [`${t.title} (${open.length})`, '', ...lines, '', `———\n${t.hint}`].join('\n'),
  },
}];

/* ══════════════════════════════════════════════════════════════════════
 *  🧾 PARSE DAILY REPORT
 *  متن آزاد کاربر را به یک ردیف ساختاریافتهٔ آرشیو تبدیل می‌کند.
 *  Turns the user's free-form message into one structured archive row.
 * ══════════════════════════════════════════════════════════════════════ */
const CFG = { lang: 'fa', tz: 'Asia/Tehran', minChars: 3 };

const L = {
  fa: {
    saved: '🗄 <b>گزارش امروز ذخیره شد</b>',
    items: 'مورد',
    hours: 'ساعت',
    mood: 'حال',
    off: '🌴 <b>امروز مرخصی ثبت شد</b>',
    short: '⚠️ گزارش خیلی کوتاه است. لطفاً کمی توضیح بده.',
    tip: 'گزارش تجمیعی ماه، اول ماه بعد برایت می‌آید.',
    wd: ['یکشنبه', 'دوشنبه', 'سه‌شنبه', 'چهارشنبه', 'پنجشنبه', 'جمعه', 'شنبه'],
  },
  en: {
    saved: '🗄 <b>Daily report saved</b>',
    items: 'item(s)',
    hours: 'hours',
    mood: 'mood',
    off: '🌴 <b>Day off recorded</b>',
    short: '⚠️ That report is very short. Add a bit more detail.',
    tip: 'Your monthly roll-up arrives on the 1st.',
    wd: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
  },
};
const t = L[CFG.lang] || L.en;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const inp = $json;
const now = $now.setZone(CFG.tz);
const isOff = inp.command === 'off';

// اگر پیام با دستور شروع شده باشد فقط بدنهٔ آن گزارش است / strip a leading command
let text = String((inp.command ? inp.args : inp.text) || '').trim();

// ساعت: 6.5  /  hours: 6.5
let hours = '';
text = text.replace(/(^|\s)(ساعت|hours?|hrs?)\s*[:：=]?\s*(\d+(?:[.,]\d+)?)/gi, (_, sp, __, v) => {
  hours = String(v).replace(',', '.'); return sp;
}).trim();

// حال: خوب  /  mood: good
let mood = '';
text = text.replace(/(^|\s)(حال|mood)\s*[:：=]?\s*([^\s،,]+)/gi, (_, sp, __, v) => {
  mood = v; return sp;
}).trim();

// #تگ‌ها  /  #tags
const tags = [];
text = text.replace(/(^|\s)#([^\s#]+)/g, (_, sp, v) => { tags.push(v); return sp; }).trim();

const lines = text.split(/\r?\n/).map((l) => l.replace(/^\s*[-•*—]\s*/, '').trim()).filter(Boolean);
const clean = lines.join('\n');

if (!isOff && clean.length < CFG.minChars) {
  return { json: { chatId: inp.chatId, ok: false, skipArchive: true, message: t.short } };
}

const jsWeekday = now.weekday % 7; // luxon: 1=Mon..7=Sun  →  0=Sun..6=Sat
const row = {
  date:        now.toISODate(),
  weekday:     t.wd[jsWeekday] || '',
  report:      isOff ? 'OFF' : clean,
  items_count: isOff ? 0 : lines.length,
  done_count:  isOff ? 0 : lines.length,
  hours:       isOff ? 0 : (hours === '' ? '' : Number(hours)),
  tags:        tags.join(','),
  mood:        isOff ? 'off' : mood,
  source:      inp.source || '',
  owner:       inp.userName || inp.userId || '',
  chat_id:     inp.chatId || '',
  created_at:  now.toISO(),
};

const summary = isOff
  ? `${t.off}\n<i>${row.date}</i>`
  : [
      t.saved,
      `<i>${row.date} · ${esc(row.weekday)}</i>`,
      '',
      ...lines.slice(0, 12).map((l) => `• ${esc(l)}`),
      '',
      `📊 ${lines.length} ${t.items}` +
        (hours ? ` · ⏱ ${esc(hours)} ${t.hours}` : '') +
        (mood ? ` · 🙂 ${esc(mood)}` : ''),
      tags.length ? `🏷 #${tags.map(esc).join(' #')}` : '',
      '',
      `<i>${t.tip}</i>`,
    ].filter((x) => x !== null).join('\n');

return { json: { ...row, chatId: inp.chatId, ok: true, skipArchive: false, message: summary } };

// 🚫 کاربر غیرمجاز / unauthorized user
// فهرست سفید در نود «🔀 Normalize Input» تنظیم می‌شود.
// The allowlist lives in the "🔀 Normalize Input" node.
return {
  json: {
    chatId: $json.chatId,
    message: '⛔️ این ربات فقط برای کاربران مجاز است.\n⛔️ This bot is restricted to authorised users.',
  },
};
